C_PCHAR get_camera_gui_error_str( INT32 guierror )
{
	C_PCHAR mess;
	switch( guierror )
	{	 
	case PGRCAMGUI_FAILED:						mess = "Function failed";					break;
	case PGRCAMGUI_COULD_NOT_CREATE_DIALOG:		mess = "Was unable to create dialog";		break;
	case PGRCAMGUI_INVALID_ARGUMENT:			mess = "An invalid argument was passed";	break;
	case PGRCAMGUI_INVALID_CONTEXT:				mess = "An invalid context was passed";		break;
	case PGRCAMGUI_MEMORY_ALLOCATION_ERROR:		mess = "Memory allocation error";			break;
	case PGRCAMGUI_INTERNAL_CAMERA_ERROR:		mess = "There has been an internal camera error - call getLastError()";	break;
	default:									mess = "unknown CameraGUIError";			break;
	}
	return mess;
}

C_PCHAR get_digiclops_error_str( INT32 digiclops_error )
{
	C_PCHAR mess;
	switch( digiclops_error )
	{	 
	case DIGICLOPS_OK:							mess = "Function completed successfully";		break;
	case DIGICLOPS_ALREADY_INITIALIZED:			mess = "Device already initialized.";			break;
	case DIGICLOPS_ALREADY_STARTED:				mess = "Grabbing has already been started";		break;
	case DIGICLOPS_CALLBACK_NOT_REGISTERED:		mess = "Callback is not registered";			break;
	case DIGICLOPS_CALLBACK_ALREADY_REGISTERED:	mess = "Callback is already registered";		break;
	case DIGICLOPS_CAMERACONTROL_PROBLEM:		mess = "Problem controlling camera";			break;
	case DIGICLOPS_COULD_NOT_OPEN_FILE:			mess = "Failed to open file.";					break;
	case DIGICLOPS_FAILED:						mess = "General failure";						break;
	case DIGICLOPS_INVALID_ARGUMENT:			mess = "Invalid argument passed";				break;
	case DIGICLOPS_INVALID_CONTEXT:				mess = "Invalid context passed";				break;
	case DIGICLOPS_INVALID_IMAGE_TYPE:			mess = "Invalid image type passed";				break;
	case DIGICLOPS_ISOCH_GRAB_ERROR:			mess = "Isoch grab error occured";				break;
	case DIGICLOPS_ISOCH_GRAB_NOT_STARTED:		mess = "Isoch grab not starte";					break;
	case DIGICLOPS_ISOCH_GRAB_SHUTDOWN_ERROR:	mess = "Error shutting down isoch grab";		break;
	case DIGICLOPS_MEMORY_ALLOC_ERROR:			mess = "Memory allocation error";				break;
	case DIGICLOPS_NO_IMAGE:					mess = "DigiclopsGrabImage() not called.";		break;
	case DIGICLOPS_NO_TRICLOPS_CONTEXT_FOUND:	mess = "No Triclops context found on camera";	break;
	case DIGICLOPS_NOT_IMPLEMENTED:				mess = "Function not implemented";				break;
	case DIGICLOPS_NOT_INITIALIZED:				mess = "Device not initialized";				break;
	case DIGICLOPS_NOT_STARTED:					mess = "DigiclopsStart() not called";			break;
	case DIGICLOPS_MAX_BANDWIDTH_EXCEEDED:		mess = "Request would exceed maximum bandwidth";		break;
	case DIGICLOPS_NON_PGR_CAMERA:				mess = "Attempt to use driver on non-PGR camera";		break;
	case DIGICLOPS_INVALID_MODE:				mess = "Invalid mode or framerate set or retrieved";	break;
	case DIGICLOPS_ERROR_UNKNOWN:
	default:									mess = "unknown DigiclopsError";				break;
	}
	return mess;
}

C_PCHAR	triclops_get_error_str( INT32 err_num )
{
	C_PCHAR	str;
	switch( err_num )
	{
	case	TriclopsErrorInvalidContext:		str="The TriclopsContext passed in was corrupt or invalid.";		break;
		// The specified camera is not valid for this camera configuration.
	case	TriclopsErrorInvalidCamera:			str="The camera does not match a camera in this configuration.";	break;
		// Given the current specified options, the request is not valid. 
		// For example, requesting the disparity image from a context that has 
		// not executed 'triclopsStereo()'. 
	case	TriclopsErrorInvalidRequest:			str="The image type does not match the camera or is not being generated by this system with the current context options.";	break;
	case	TriclopsErrorInvalidSetting:			str="User specified input to the function that was not a valid value for this function.";	break;
	case	TriclopsErrorNotImplemented:			str="User requested an option that is not yet implemented";	break;
	case	TriclopsErrorInvalidROI:				str="An impossible Region Of Interest was specified. For example, a region of interest with negative height or width";	break;
	case	TriclopsErrorBadOptions:				str="Some options are illegal or contradictory";	break;
	case	TriclopsErrorCorruptConfigFile:			str="The configuration file is corrupted, missing mandatory fields or is for the wrong Triclops version";	break;
	case	TriclopsErrorNoConfigFile:				str="Can not find the configuration file";	break;
	case	TriclopsErrorUnknown:					str="An indeterminable error occurred";	break;
	case	TriclopsErrorNonMMXCpu:					str="A function that requires MMX was called on a non-MMX enabled CPU";	break;
	case	TriclopsErrorInvalidParameter:			str="An invalid parameter has been passed.";	break;
	case	TriclopsErrorSurfaceValidationOverflow:	str="A call to TriclopsSetSurfaceValidation has caused an overflow";	break;
	case	TriclopsErrorSystemError:				str="An error has occurred during a system call. Check 'errno' to determine the reason. This includes the system running out of memory";	break;
	case	TriclopsErrorCorruptTransformFile:		str="Can not find the transform file or its contents is invalid";	break;
	case	TriclopsErrorFileRead:					str="Error reading in a file";	break;
	case	TriclopsErrorCorruptPGRComment:			str="The PGR comment in a PGM header was corrupted";	break;
	case	TriclopsErrorDeprecated:				str="This Triclops functionality has been deprecated";	break;

		//TriclopsErrorOk = 0,
	default:	str="triclops error not documented yet.";	break;
	}
	return str;
}

#endif
